"use client";

import { FormEvent, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { ArrowRight, ArrowUpRight, Check, Clipboard, Info, LoaderCircle, Stethoscope, TriangleAlert, X } from "lucide-react";
import type { Diagnostic, WebDoctorReport, WebDoctorReportSnapshot, WebDoctorStreamEvent } from "@/types/web-doctor";
import { failureClass, scoreBand, trackProductEvent, type AnalysisSource, type FeedbackReason } from "@/lib/analytics/product-events";
import { saveCrossToolState } from "@/lib/lab/cross-tool-state";
