type DisplayStatus="pass"|"info"|"improve"|"important";
function displayStatus(item:Diagnostic):DisplayStatus{if(item.scoreable===false||item.id==="favicon"||(item.id==="robots-file"&&item.value==="Not found"))return "info";if(item.status==="pass")return "pass";if(item.status==="error"&&["title","indexing","canonical","response"].includes(item.id))return "important";return "improve";}
function DisplayStatusIcon({status}:{status:DisplayStatus}){return status==="pass"?<Check aria-hidden="true" />:status==="info"?<Info aria-hidden="true" />:status==="important"?<X aria-hidden="true" />:<TriangleAlert aria-hidden="true" />;}
function priorityLabel(item:Diagnostic,status:DisplayStatus){if(status==="important")return "High priority";if(status==="info"&&item.id==="favicon")return "Low priority";return "";}

const editableChecks:Record<string,{label:string;placeholder:string;multiline?:boolean}>={title:{label:"Write your page title",placeholder:"Primary topic and value | Brand"},description:{label:"Write your meta description",placeholder:"Explain what this page offers, who it helps and why it is useful.",multiline:true},canonical:{label:"Enter the preferred page URL",placeholder:"https://example.com/page"},h1:{label:"Write the primary heading",placeholder:"One clear description of this page"},language:{label:"Enter the language code",placeholder:"en"}};
const defaultImplementations:Record<string,string>={"heading-order":"<!-- Keep heading levels sequential: h1 → h2 → h3. -->",viewport:'<meta name="viewport" content="width=device-width, initial-scale=1" />',indexing:'<meta name="robots" content="index, follow" />',"robots-file":"User-agent: *\nAllow: /\n\nSitemap: https://example.com/sitemap.xml","sitemap-file":'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url><loc>https://example.com/[page-path]</loc></url>\n</urlset>',social:'<meta property="og:title" content="[Page title]" />\n<meta property="og:description" content="[Page description]" />\n<meta property="og:image" content="https://example.com/[social-image].jpg" />',twitter:'<meta name="twitter:card" content="summary_large_image" />\n<meta name="twitter:title" content="[Page title]" />\n<meta name="twitter:description" content="[Page description]" />\n<meta name="twitter:image" content="https://example.com/[social-image].jpg" />',images:'<img src="[image-file].jpg" alt="[Describe the image purpose]" />',links:'<a href="/[destination]">[Descriptive link text]</a>',schema:'<script type="application/ld+json">{"@context":"https://schema.org","@type":"WebPage","name":"[Page title]","url":"[Canonical URL]"}</script>',charset:'<meta charset="utf-8" />',favicon:'<link rel="icon" href="/favicon.ico" />',hreflang:'<link rel="alternate" hreflang="en-GB" href="https://example.com/[regional-page]" />',response:"Configure this route to return HTTP 200 after rendering the requested page.",https:"Install a valid TLS certificate and redirect every HTTP request to HTTPS.","security-headers":"Content-Security-Policy: default-src 'self'\nStrict-Transport-Security: max-age=31536000; includeSubDomains\nX-Content-Type-Options: nosniff\nReferrer-Policy: strict-origin-when-cross-origin"};
function escapeMarkup(value:string){return value.replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function buildFix(item:Diagnostic,value:string){const safe=escapeMarkup(value.trim());if(item.id==="title")return `<title>${safe}</title>`;if(item.id==="description")return `<meta name="description" content="${safe}" />`;if(item.id==="canonical")return `<link rel="canonical" href="${safe}" />`;if(item.id==="h1")return `<h1>${safe}</h1>`;if(item.id==="language")return `<html lang="${safe}">`;return value.trim();}
function validateFix(item:Diagnostic,value:string){const clean=value.trim();if(!clean)return "Add a value before copying the fix.";if(item.id==="canonical"){try{const url=new URL(clean);if(!/^https?:$/.test(url.protocol))throw new Error();}catch{return "Enter a complete HTTP or HTTPS URL.";}}if(item.id==="h1"&&clean.length<5)return "Use a clear heading of at least 5 characters.";if(item.id==="language"&&!/^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/i.test(clean))return "Use a language tag such as en, en-GB or zh-Hant.";if(item.id==="schema"){const json=clean.match(/<script[^>]*>([\s\S]*?)<\/script>/i)?.[1]??clean;try{JSON.parse(json);}catch{return "The JSON-LD must contain valid JSON.";}}const required:Record<string,RegExp>={viewport:/name=["']viewport/i,charset:/charset\s*=/i,favicon:/rel=["'][^"']*icon/i,indexing:/name=["']robots/i,"robots-file":/user-agent\s*:/i,"sitemap-file":/<urlset\b/i,social:/og:title[\s\S]*og:description[\s\S]*og:image/i,twitter:/twitter:card/i,images:/\balt=["'][^"']+/i,links:/<a\b[^>]*href=["'][^"']+["'][^>]*>[^<]+/i,hreflang:/hreflang=["'][a-z-]+["']/i,"security-headers":/content-security-policy\s*:/i};if(required[item.id]&&!required[item.id].test(clean))return "The implementation is incomplete. Keep the required attribute or directive in the generated fix.";return "";}
function initialFixValue(item:Diagnostic){if(item.id==="title"&&item.value==="Not found")return "[Your Page Title]";if(item.id==="description"&&item.value==="Missing")return "[Describe this page clearly for the people it is intended to help]";if(item.id==="canonical"&&item.value==="Missing")return item.fix?.match(/href="([^"]+)"/)?.[1]??"";if(item.id==="language"&&item.value==="Missing")return "en";if(item.id==="h1")return item.headingAnalysis?.items.find(heading=>heading.level===1&&heading.text)?.text??"[Primary page heading]";if(editableChecks[item.id])return item.value!=="Missing"?item.value:"";return item.fix??defaultImplementations[item.id]??`Review and update: ${item.label}`;}
type FixFramework="HTML"|"Next.js"|"React"|"WordPress";
const frameworkIssues=new Set(["title","description","canonical","indexing","viewport","social","twitter","schema","language","favicon"]);
function frameworkFix(item:Diagnostic,value:string,html:string,framework:FixFramework){if(framework==="HTML")return html;const clean=value.trim(),quoted=JSON.stringify(clean);if(framework==="Next.js"){const fixes:Record<string,string>={title:`export const metadata = {\n  title: ${quoted},\n};`,description:`export const metadata = {\n  description: ${quoted},\n};`,canonical:`export const metadata = {\n  alternates: { canonical: ${quoted} },\n};`,indexing:"export const metadata = {\n  robots: { index: true, follow: true },\n};",viewport:"export const viewport = {\n  width: 'device-width',\n  initialScale: 1,\n};",social:"export const metadata = {\n  openGraph: {\n    title: '[Page title]',\n    description: '[Page description]',\n    images: ['https://example.com/[social-image].jpg'],\n  },\n};",twitter:"export const metadata = {\n  twitter: {\n    card: 'summary_large_image',\n    title: '[Page title]',\n    description: '[Page description]',\n    images: ['https://example.com/[social-image].jpg'],\n  },\n};",schema:"// Add this in the relevant layout or page component.\n<script type=\"application/ld+json\" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />",language:`// app/layout.tsx\n<html lang=${quoted}>{'{children}'}</html>`,favicon:"export const metadata = {\n  icons: { icon: '/favicon.ico', apple: '/apple-touch-icon.png' },\n  manifest: '/site.webmanifest',\n};"};return fixes[item.id]??html;}if(framework==="React"){const fixes:Record<string,string>={title:`// In the page component\ndocument.title = ${quoted};`,description:`<meta name=\"description\" content={${quoted}} />`,canonical:`<link rel=\"canonical\" href={${quoted}} />`,indexing:'<meta name="robots" content="index, follow" />',viewport:'<meta name="viewport" content="width=device-width, initial-scale=1" />',social:"<>\n  <meta property=\"og:title\" content=\"[Page title]\" />\n  <meta property=\"og:description\" content=\"[Page description]\" />\n  <meta property=\"og:image\" content=\"https://example.com/[social-image].jpg\" />\n</>",twitter:"<>\n  <meta name=\"twitter:card\" content=\"summary_large_image\" />\n  <meta name=\"twitter:title\" content=\"[Page title]\" />\n  <meta name=\"twitter:description\" content=\"[Page description]\" />\n</>",schema:"<script type=\"application/ld+json\">\n  {JSON.stringify(schema)}\n</script>",language:`document.documentElement.lang = ${quoted};`,favicon:'<link rel="icon" href="/favicon.ico" />'};return fixes[item.id]??html;}const phpValue=clean.replace(/\\/g,"\\\\").replace(/'/g,"\\'");const fixes:Record<string,string>={title:`// functions.php — uses WordPress core, no SEO plugin required.\nadd_filter( 'pre_get_document_title', function () {\n    return '${phpValue}';\n} );`,description:`// functions.php — replace the placeholder with page-specific owner-authored text.\nadd_action( 'wp_head', function () {\n    echo '<meta name=\"description\" content=\"' . esc_attr( '${phpValue}' ) . '\">';\n} );`,canonical:`// functions.php — output one preferred URL.\nadd_action( 'wp_head', function () {\n    echo '<link rel=\"canonical\" href=\"' . esc_url( '${phpValue}' ) . '\">';\n} );`,indexing:"// Prefer WordPress Settings → Reading for site-wide visibility.\n// For custom code, use the core wp_robots filter.",viewport:"<!-- Add to header.php inside <head>. -->\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",social:"<!-- Add equivalent og:* tags through your theme's wp_head output. -->\n<!-- Do not install or assume a specific SEO plugin solely for this snippet. -->\n"+html,twitter:"<!-- Add equivalent twitter:* tags through your theme's wp_head output. -->\n"+html,schema:"<!-- Add validated JSON-LD through a theme or custom plugin wp_head hook. -->\n"+html,language:"<!-- In the theme's header.php: -->\n<html <?php language_attributes(); ?>>",favicon:"Use Appearance → Customize → Site Identity → Site Icon.\nThis uses WordPress core and does not require an SEO plugin."};return fixes[item.id]??`// Add this through your theme or a small custom plugin.\n${html}`;}
function FixBuilder({item}:{item:Diagnostic}){const config=editableChecks[item.id];const [value,setValue]=useState(()=>initialFixValue(item));const [framework,setFramework]=useState<FixFramework>("HTML");const [copied,setCopied]=useState(false);const validation=validateFix(item,value);const htmlResult=buildFix(item,value),result=frameworkFix(item,value,htmlResult,framework);const characterCount=Array.from(value.trim()).length;const feedback=!validation&&item.id==="title"?`${characterCount} characters. Replace bracketed placeholder text with your own accurate title.`:!validation&&item.id==="description"?`${characterCount} characters. Replace bracketed placeholder text with your own summary; search engines may use a different snippet.`:validation||"Valid — your edited result is ready to copy.";async function copy(){if(validation)return;await navigator.clipboard.writeText(result);trackProductEvent("fix_copied",{findingId:item.id,framework});setCopied(true);window.setTimeout(()=>setCopied(false),1800);}return <div className="finding-fix"><span>Editable implementation</span><label htmlFor={`fix-${item.id}`}>{config?.label??"Edit the implementation below"}</label>{config&&!config.multiline?<input id={`fix-${item.id}`} value={value} placeholder={config.placeholder} aria-describedby={`fix-feedback-${item.id}`} aria-invalid={Boolean(validation)} onChange={event=>setValue(event.target.value)} />:<textarea id={`fix-${item.id}`} value={value} placeholder={config?.placeholder??"Enter or edit the implementation"} aria-describedby={`fix-feedback-${item.id}`} aria-invalid={Boolean(validation)} onChange={event=>setValue(event.target.value)} />}<small id={`fix-feedback-${item.id}`} className={validation?"fix-validation is-invalid":"fix-validation is-valid"} aria-live="polite">{feedback}</small>{frameworkIssues.has(item.id)&&<div className="fix-framework-tabs" role="group" aria-label="Choose implementation framework">{(["HTML","Next.js","React","WordPress"] as FixFramework[]).map(option=><button type="button" aria-pressed={framework===option} className={framework===option?"is-active":""} onClick={()=>{setFramework(option);setCopied(false);}} key={option}>{option}</button>)}</div>}<span className="fix-result-label">{framework} implementation</span><pre><code>{result||"Your generated fix will appear here."}</code></pre><button className="fix-copy" type="button" disabled={Boolean(validation)} aria-label={copied?`${framework} fix for ${item.label} copied`:`Copy ${framework} fix for ${item.label}`} onClick={()=>void copy()}><Clipboard aria-hidden="true" /> <span aria-live="polite">{copied?"Copied":"Copy"}</span></button></div>;}
function HeadingOutline({analysis}:{analysis:NonNullable<Diagnostic["headingAnalysis"]>}){return <div className="heading-analysis"><dl><div><dt>H1 elements</dt><dd>{analysis.h1Count}</dd></div><div><dt>Empty headings</dt><dd>{analysis.emptyCount}</dd></div><div><dt>Skipped levels</dt><dd>{analysis.skippedCount}</dd></div><div><dt>Total headings</dt><dd>{analysis.total}</dd></div></dl><div className="heading-tree" aria-label="Detected heading outline">{analysis.items.length?analysis.items.map((heading,index)=>{const lastAtLevel=!analysis.items.slice(index+1).some(next=>next.level<=heading.level);return <div className={heading.text?"":"is-empty"} style={{paddingInlineStart:`${Math.max(0,heading.level-1)*1.35}rem`}} key={`${heading.level}-${index}`}><span className="heading-branch" aria-hidden="true">{heading.level===1?"":lastAtLevel?"└─":"├─"}</span><b>H{heading.level}</b><span>{heading.text||"Empty heading"}</span></div>;}):<p>No H1–H6 elements were detected.</p>}</div></div>;}
function CanonicalDetails({analysis}:{analysis:NonNullable<Diagnostic["canonicalAnalysis"]>}){return <div className="canonical-analysis"><dl><div><dt>Tags found</dt><dd>{analysis.count}</dd></div><div><dt>Format</dt><dd>{analysis.malformed?"Malformed":analysis.absolute?"Absolute":"Relative"}</dd></div><div><dt>Protocol</dt><dd>{analysis.httpOnHttps?"HTTP on HTTPS page":"Consistent"}</dd></div><div><dt>Host</dt><dd>{analysis.differentHost?"Different host":"Same host"}</dd></div></dl>{analysis.values.length>1&&<div><strong>Canonical tags detected</strong><ol>{analysis.values.map((value,index)=><li key={`${value}-${index}`}>{value||"Empty href"}</li>)}</ol></div>}</div>;}
function IndexabilityDetails({analysis}:{analysis:NonNullable<Diagnostic["indexabilityAnalysis"]>}){return <dl className="indexability-sources"><div><dt>Meta robots</dt><dd>{analysis.metaRobots||"Not present"}</dd></div><div><dt>X-Robots-Tag</dt><dd>{analysis.headerRobots||"Not present"}</dd></div><div><dt>Link following</dt><dd>{analysis.nofollow?"nofollow detected":analysis.usesDefault?"Default behaviour":"follow permitted"}</dd></div></dl>;}
function RobotsDetails({analysis}:{analysis:NonNullable<Diagnostic["robotsAnalysis"]>}){return <div className="robots-analysis"><div><span>Location</span>{analysis.url?<a href={analysis.url} target="_blank" rel="noreferrer">{analysis.url}</a>:<strong>Standard origin location</strong>}<small>{analysis.status?`HTTP ${analysis.status}`:"No successful response"}</small></div>{analysis.directives.length>0&&<div><span>Basic relevant directives</span><dl>{analysis.directives.map((directive,index)=><div key={`${directive.name}-${index}`}><dt>{directive.name}</dt><dd>{directive.value||"(empty)"}</dd></div>)}</dl></div>}</div>;}
function SitemapDetails({analysis}:{analysis:NonNullable<Diagnostic["sitemapAnalysis"]>}){return <div className="sitemap-analysis"><div><span>Location</span>{analysis.found?<a href={analysis.url} target="_blank" rel="noreferrer">{analysis.url}</a>:<strong>No valid XML sitemap detected</strong>}<small>{analysis.source==="none"?"Checked robots.txt, /sitemap.xml and /sitemap_index.xml":`Discovered via ${analysis.source}`}</small></div><dl><div><dt>URLs discovered</dt><dd>{analysis.urlCount}</dd></div>{analysis.isIndex&&<div><dt>Child sitemaps listed</dt><dd>{analysis.sitemapCount}</dd></div>}<div><dt>Files downloaded recursively</dt><dd>0</dd></div></dl><button type="button" disabled title="Full-site crawling is planned for a safely bounded future version">Analyse website pages <span>Coming later</span></button></div>;}
function OpenGraphDetails({analysis,pageUrl}:{analysis:NonNullable<Diagnostic["openGraphAnalysis"]>;pageUrl:string}){const [showMissingImagePreview,setShowMissingImagePreview]=useState(false);const values=[['og:title',analysis.title],['og:description',analysis.description],['og:image',analysis.image],['og:url',analysis.url],['og:type',analysis.type],['og:site_name',analysis.siteName]];let displayUrl=analysis.url||pageUrl;try{displayUrl=new URL(displayUrl).hostname;}catch{}const imageMissing=analysis.imageStatus==="missing",showPreview=!imageMissing||showMissingImagePreview,implementation='<meta property="og:image" content="https://example.com/social-image.jpg" />\n<meta property="og:image:width" content="1200" />\n<meta property="og:image:height" content="630" />\n<meta property="og:image:alt" content="[Describe the image]" />';return <div className="open-graph-analysis"><dl>{values.map(([name,value])=><div key={name}><dt>{name}</dt><dd>{value||"Not found"}</dd></div>)}</dl><div className="open-graph-preview-workflow">{imageMissing&&!showMissingImagePreview&&<button className="social-preview-trigger" type="button" onClick={()=>setShowMissingImagePreview(true)}>Preview social card <ArrowRight aria-hidden="true" /></button>}{showPreview&&<><article className="social-card" aria-label="Current social sharing preview"><span>CURRENT SOCIAL PREVIEW</span>{analysis.imagePreview?<div className="social-card-image" role="img" aria-label="Detected Open Graph image" style={{backgroundImage:`url(${analysis.imagePreview})`}} />:<div className="social-card-fallback"><span>{imageMissing?"No social image":"Image preview unavailable"}</span><small>{imageMissing?"This is how the card may appear without og:image.":"The image was unsafe, inaccessible, unsupported, or too large"}</small></div>}<div className="social-card-copy"><small>{displayUrl}</small><h4>{analysis.title||"No Open Graph title detected"}</h4><p>{analysis.description||"No Open Graph description detected."}</p></div></article>{imageMissing&&<section className="og-image-guidance"><div><span>Recommended starting point</span><strong>1200 × 630 px</strong><p>Use a clear landscape image that remains understandable when platforms crop it. Keep essential text and subjects away from the edges. Platforms may apply their own crop or ignore supplied metadata.</p></div><div><span>Implementation</span><ol><li>Create and publish the image at a stable public HTTPS URL.</li><li>Add an absolute <code>og:image</code> URL in the page head.</li><li>Include accurate width, height and alt metadata where practical.</li><li>Recheck the page, then test it with the sharing platform you support.</li></ol><CopySnippet code={implementation} onCopied={()=>trackProductEvent("fix_copied",{findingId:"social",framework:"HTML"})} /></div></section>}</>}</div></div>;}
function TwitterDetails({analysis}:{analysis:NonNullable<Diagnostic["twitterAnalysis"]>}){const values=[['twitter:card',analysis.card],['twitter:title',analysis.title],['twitter:description',analysis.description],['twitter:image',analysis.image]];return <div className="twitter-analysis"><dl>{values.map(([name,value])=><div key={name}><dt>{name}</dt><dd>{value||"Not found"}</dd></div>)}</dl>{analysis.usesOpenGraphFallback&&analysis.fieldCount<4&&<p><Check aria-hidden="true" /> Complete Open Graph fallback detected</p>}</div>;}
function LinkDetails({analysis}:{analysis:NonNullable<Diagnostic["linkAnalysis"]>}){const counts=[['Internal',analysis.internal],['External',analysis.external],['Email',analysis.email],['Telephone',analysis.telephone],['HTTP links',analysis.http],['Empty href',analysis.empty],['Hash-only href',analysis.hashOnly],['JavaScript links',analysis.javascript]];return <div className="link-analysis"><dl>{counts.map(([label,value])=><div className={Number(value)>0&&['Empty href','Hash-only href','JavaScript links'].includes(String(label))?"has-problem":""} key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><div><strong>No destination crawling</strong><p>Only links in this page’s HTML were classified. External and internal destinations were not fetched.</p><button type="button" disabled>Check link destinations <span>Future tool</span></button></div></div>;}
function SiteIdentityDetails({analysis}:{analysis:NonNullable<Diagnostic["siteIdentityAnalysis"]>}){const assets=[{label:"Favicon",...analysis.favicon},{label:"Touch icon",...analysis.touchIcon}];return <div className="site-identity-analysis">{assets.map(asset=><div key={asset.label}>{asset.preview?<span className="identity-preview" role="img" aria-label={`${asset.label} preview`} style={{backgroundImage:`url(${asset.preview})`}} />:<span className="identity-fallback" aria-hidden="true">{asset.label.slice(0,1)}</span>}<div><strong>{asset.label}</strong><small>{asset.url||"Not declared"}</small></div><b aria-label={asset.available?"Available":"Unavailable"}>{asset.available?"✓":"—"}</b></div>)}<div><span className="identity-fallback" aria-hidden="true">M</span><div><strong>Manifest</strong><small>{analysis.manifest.url||"Not declared"}{analysis.manifest.available&&!analysis.manifest.valid?" · invalid JSON":""}</small></div><b aria-label={analysis.manifest.available&&analysis.manifest.valid?"Available":"Unavailable"}>{analysis.manifest.available&&analysis.manifest.valid?"✓":"—"}</b></div></div>;}
function StructuredDataDetails({analysis}:{analysis:NonNullable<Diagnostic["structuredDataAnalysis"]>}){return <div className="structured-data-analysis"><dl><div><dt>Valid JSON</dt><dd>{analysis.valid?"✓":"No"}</dd></div><div><dt>JSON-LD blocks</dt><dd>{analysis.blocks}</dd></div><div><dt>Schemas</dt><dd>{analysis.schemas}</dd></div></dl><div><strong>Detected types</strong>{analysis.types.length?<ul>{analysis.types.map(type=><li key={type}>{type}</li>)}</ul>:<p>No @type values detected.</p>}{analysis.errors.length>0&&<div className="schema-errors"><strong>Parsing problems</strong>{analysis.errors.map(error=><p key={error}>{error}</p>)}</div>}</div></div>;}
function HreflangDetails({analysis}:{analysis:NonNullable<Diagnostic["hreflangAnalysis"]>}){return <div className="hreflang-analysis"><div className="hreflang-summary"><span>Invalid <b>{analysis.invalid}</b></span><span>Duplicates <b>{analysis.duplicates}</b></span></div><dl>{analysis.items.map((item,index)=><div key={`${item.lang}-${index}`}><dt>{item.lang||"Empty language"}</dt><dd>{item.href||"Missing destination"}</dd></div>)}</dl></div>;}
function SecurityBasicsDetails({analysis}:{analysis:NonNullable<Diagnostic["securityBasicsAnalysis"]>}){const checks=[['HTTPS',analysis.https],['Content-Security-Policy',analysis.csp],['Strict-Transport-Security',analysis.hsts],['X-Content-Type-Options',analysis.contentTypeOptions],['Referrer-Policy',analysis.referrerPolicy],['Permissions-Policy',analysis.permissionsPolicy],['Frame protection',analysis.frameProtection]];return <div className="security-basics-analysis">{checks.map(([label,present])=><div key={String(label)}><span>{label}</span><b className={present?"is-present":""}>{present?"✓":"—"}</b></div>)}</div>;}
function ContentOverviewDetails({analysis}:{analysis:NonNullable<Diagnostic["contentOverviewAnalysis"]>}){const metrics=[['Words',`~${analysis.words.toLocaleString("en-GB")}`],['Paragraphs',analysis.paragraphs],['Headings',analysis.headings],['Links',analysis.links],['Images',analysis.images]];const landmarks=[['Main landmark',analysis.main],['Header',analysis.header],['Footer',analysis.footer],['Navigation',analysis.navigation]];return <div className="content-overview-analysis"><dl>{metrics.map(([label,value])=><div key={String(label)}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><div><strong>Page landmarks</strong>{landmarks.map(([label,present])=><span key={String(label)}>{label}<b>{present?"✓":"—"}</b></span>)}</div></div>;}
const findingGuides:Record<string,{slug:string;label:string}>={title:{slug:"title-tags",label:"How title tags work"},description:{slug:"meta-descriptions",label:"How meta descriptions work"},canonical:{slug:"canonical-urls",label:"How canonical URLs work"},indexing:{slug:"robots-txt",label:"How crawl and index controls work"},"robots-file":{slug:"robots-txt",label:"How robots.txt works"},social:{slug:"open-graph",label:"How Open Graph works"},twitter:{slug:"open-graph",label:"How social metadata works"},schema:{slug:"structured-data",label:"How structured data works"}};
function recommendedAction(item:Diagnostic,tone:DisplayStatus){let action="Review the detected value and use the implementation below as a starting point for a suitable correction.";if(item.availability==="unavailable")action="No change is recommended from an incomplete check. Check the page again later while reviewing the available findings in this report.";else if(item.id==="indexing"&&tone==="important")action="Remove the noindex or none directive only if this page is intended to appear in search results. Check both the HTML meta tag and the response header.";else if(item.id==="title"&&tone==="important")action="Write one accurate, descriptive page title that helps people understand the page before they visit it.";else if(item.id==="canonical"&&tone==="important")action="Declare one valid absolute canonical URL that represents the preferred version of this page.";else if(item.id==="response"&&tone==="important")action="Correct the route or server response so the public page returns a successful 2xx status.";else if(tone==="pass")action="No immediate change is required. Keep this value accurate when the page changes.";else if(tone==="info")action="Use this information for context. Make a change only when it supports the page or your technical requirements.";const guide=findingGuides[item.id];return <>{action}{guide&&item.availability!=="unavailable"&&<Link className="finding-guide-link" href={`/guides/${guide.slug}`} onClick={()=>trackProductEvent("guide_opened",{guideSlug:guide.slug,findingId:item.id})}>{guide.label} <span aria-hidden="true">→</span></Link>}</>;}
function FindingDetails({item,pageUrl}:{item:Diagnostic;pageUrl:string}){const isTitle=item.id==="title",isDescription=item.id==="description",present=(isTitle&&item.value!=="Not found")||(isDescription&&item.value!=="Missing"),tone=displayStatus(item),priority=priorityLabel(item,tone),unavailable=item.availability==="unavailable";return <article className={`finding finding-tone-${tone}`}><div className="finding-status"><DisplayStatusIcon status={tone} /><div><span>{unavailable?"UNAVAILABLE":tone.toUpperCase()}</span>{priority&&<small>{priority}</small>}</div></div><div className="finding-content"><h3>{item.label}</h3><section className="result-explanation"><h4>What did we find?</h4><strong>{isDescription&&present?`“${item.value}”`:item.value}</strong>{(isTitle||isDescription)&&present&&<span className="finding-character-count">{isDescription?"Characters: ":""}{Array.from(item.value).length}{isTitle?" characters":""}</span>}</section>{item.headingAnalysis&&<HeadingOutline analysis={item.headingAnalysis} />}{item.canonicalAnalysis&&<CanonicalDetails analysis={item.canonicalAnalysis} />}{item.indexabilityAnalysis&&<IndexabilityDetails analysis={item.indexabilityAnalysis} />}{item.robotsAnalysis&&<RobotsDetails analysis={item.robotsAnalysis} />}{item.sitemapAnalysis&&<SitemapDetails analysis={item.sitemapAnalysis} />}{item.openGraphAnalysis&&<OpenGraphDetails analysis={item.openGraphAnalysis} pageUrl={pageUrl} />}{item.twitterAnalysis&&<TwitterDetails analysis={item.twitterAnalysis} />}{item.linkAnalysis&&<LinkDetails analysis={item.linkAnalysis} />}{item.siteIdentityAnalysis&&<SiteIdentityDetails analysis={item.siteIdentityAnalysis} />}{item.structuredDataAnalysis&&<StructuredDataDetails analysis={item.structuredDataAnalysis} />}{item.hreflangAnalysis&&<HreflangDetails analysis={item.hreflangAnalysis} />}{item.securityBasicsAnalysis&&<SecurityBasicsDetails analysis={item.securityBasicsAnalysis} />}{item.contentOverviewAnalysis&&<ContentOverviewDetails analysis={item.contentOverviewAnalysis} />}<section className="result-explanation"><h4>Why might it matter?</h4><p>{item.explanation}</p></section><section className="result-explanation"><h4>What should you do?</h4><p>{recommendedAction(item,tone)}</p></section><section className="result-explanation result-fix"><h4>How do you fix it?</h4>{unavailable?<p>No implementation fix is suggested because this check did not complete.</p>:item.id==="content"?<p>No implementation fix is required for this informational content overview.</p>:<FixBuilder item={item} />}</section></div></article>;}
function issueSummary(item:Diagnostic){if(item.id==="description"&&item.value==="Missing")return "Page is missing a meta description";if(item.id==="title"&&item.value==="Not found")return "Page is missing a title";if(item.id==="indexing"&&/noindex/i.test(item.value))return "Page is marked noindex";if(item.id==="canonical"&&item.value==="Missing")return "Canonical URL is missing";if(item.id==="social"&&item.openGraphAnalysis&&!item.openGraphAnalysis.image)return "Open Graph image is missing";if(item.id==="h1"&&item.headingAnalysis?.h1Count===0)return "Page has no primary H1 heading";if(item.id==="images"&&item.status!=="pass")return "Some images are missing alt attributes";return `${item.label}: ${item.value}`;}
function ResultsSummary({report,enteredUrl,headingRef}:{report:WebDoctorReport;enteredUrl:string;headingRef:React.RefObject<HTMLHeadingElement|null>}){const counts={pass:0,info:0,improve:0,important:0};for(const item of report.diagnostics)counts[displayStatus(item)]++;const priorities=report.diagnostics.filter(item=>{const status=displayStatus(item);return status==="important"||status==="improve";}).sort((a,b)=>Number(displayStatus(b)==="important")-Number(displayStatus(a)==="important")).slice(0,5);let domain=report.url;try{domain=new URL(report.url).hostname;}catch{}const rating=report.score>=80?"GOOD":report.score>=60?"NEEDS WORK":"ATTENTION";return <header className="doctor-summary"><div className="doctor-summary-brand"><p className="eyebrow">WEB DOCTOR</p><h2 ref={headingRef} tabIndex={-1}>{domain}</h2><div className="doctor-summary-url"><span>Analysed</span>{report.url.startsWith("http")?<a href={report.url} target="_blank" rel="noreferrer">{report.url}</a>:<strong>{enteredUrl||report.url}</strong>}</div></div><div className="doctor-summary-score" aria-label={`Web Doctor score ${report.score} out of 100. Rating: ${rating}.`}><strong>{report.score}</strong><span aria-hidden="true">100</span><b>{rating}</b></div><div className="doctor-summary-counts"><strong>{counts.important} important {counts.important===1?"issue":"issues"}</strong><strong>{counts.improve} {counts.improve===1?"improvement":"improvements"}</strong><strong>{counts.pass} checks passed</strong></div><section className="doctor-priorities"><p className="eyebrow">Fix these first</p>{priorities.length?<ol>{priorities.map(item=>{const tone=displayStatus(item);return <li className={`is-${tone}`} key={item.id}><span>{issueSummary(item)}</span><b>{tone==="important"?"Important":"Improve"}</b></li>;})}</ol>:<p>No important issues or improvements were detected.</p>}</section></header>;}
const quickWinConfig:Record<string,{label:string;difficulty:"Easy"|"Moderate"|"Technical";order:number}>={title:{label:"Add or improve the page title",difficulty:"Easy",order:1},description:{label:"Add or improve the meta description",difficulty:"Easy",order:2},canonical:{label:"Add one clear canonical URL",difficulty:"Easy",order:3},social:{label:"Complete Open Graph sharing data",difficulty:"Moderate",order:4},images:{label:"Add missing image alt text",difficulty:"Moderate",order:5},language:{label:"Declare the document language",difficulty:"Easy",order:6},viewport:{label:"Add the mobile viewport",difficulty:"Easy",order:7},charset:{label:"Declare UTF-8 encoding",difficulty:"Easy",order:8},twitter:{label:"Complete Twitter/X card data",difficulty:"Moderate",order:9},h1:{label:"Clarify the heading structure",difficulty:"Moderate",order:10},indexing:{label:"Remove unintended noindex directives",difficulty:"Technical",order:11},schema:{label:"Repair invalid structured data",difficulty:"Technical",order:12}};
function QuickWins({diagnostics}:{diagnostics:Diagnostic[]}){const wins=diagnostics.filter(item=>quickWinConfig[item.id]&&item.fix&&(displayStatus(item)==="important"||displayStatus(item)==="improve")).sort((a,b)=>{const toneDifference=Number(displayStatus(b)==="important")-Number(displayStatus(a)==="important");return toneDifference||quickWinConfig[a.id].order-quickWinConfig[b.id].order;}).slice(0,4);if(!wins.length)return null;return <section className="quick-wins" aria-labelledby="quick-wins-heading"><header><p className="eyebrow">QUICK WINS</p><h2 id="quick-wins-heading">Useful changes to start with.</h2><p>Difficulty labels are broad implementation hints, not guarantees.</p></header><ol>{wins.map(item=>{const win=quickWinConfig[item.id];return <li key={item.id}><span>{win.label}</span><b>{win.difficulty}</b></li>;})}</ol></section>;}
function ReportSharing({report}:{report:WebDoctorReport}){const [copied,setCopied]=useState(false);const important=report.diagnostics.filter(item=>displayStatus(item)==="important").map(issueSummary),checkedAt=new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"long",year:"numeric",timeZone:"Europe/London"}).format(new Date(report.checkedAt));const summary=[`Web Doctor score: ${report.score}/100`,"","Important:",...(important.length?important.map(issue=>`- ${issue}`):["- None detected"]),"","Checked at:",checkedAt].join("\n");async function copySummary(){await navigator.clipboard.writeText(summary);setCopied(true);window.setTimeout(()=>setCopied(false),1800);}return <section className="report-sharing" aria-labelledby="report-sharing-heading"><div><p className="eyebrow">SHARE THE DIAGNOSIS</p><h2 id="report-sharing-heading">Take the summary with you.</h2><p>The copied summary contains only the score, important findings and check date. It does not include raw HTML or extracted page content.</p></div><div className="report-sharing-actions"><button type="button" onClick={()=>void copySummary()}><Clipboard aria-hidden="true" /> {copied?"Summary copied":"Copy summary"}</button><button type="button" onClick={()=>{trackProductEvent("report_printed",{scoreBand:scoreBand(report.score)});window.print();}}>Print / Save as PDF</button><button type="button" disabled title="Persistent report links are planned for a later version">Copy report link <span>Coming later</span></button><small>A future shareable report may store analysis results only—not raw HTML.</small></div></section>;}
type FindingStatusFilter="all"|"important"|"improve"|"pass";
type FindingTopic="all"|"seo"|"social"|"content"|"accessibility"|"technical";
const findingTopics:Record<Exclude<FindingTopic,"all">,Set<string>>={seo:new Set(["title","description","canonical","indexing","robots-file","sitemap-file","schema","hreflang"]),social:new Set(["social","twitter"]),content:new Set(["h1","links","content"]),accessibility:new Set(["images","language"]),technical:new Set(["response","viewport","charset","favicon","security-basics"])};
function FindingsExplorer({diagnostics,pageUrl}:{diagnostics:Diagnostic[];pageUrl:string}){const initialStatus:FindingStatusFilter=diagnostics.some(item=>displayStatus(item)==="important")?"important":diagnostics.some(item=>displayStatus(item)==="improve")?"improve":"all";const [statusFilter,setStatusFilter]=useState<FindingStatusFilter>(initialStatus),[topic,setTopic]=useState<FindingTopic>("all");const statuses:Array<{id:FindingStatusFilter;label:string}>=[{id:"all",label:"All"},{id:"important",label:"Important"},{id:"improve",label:"Improvements"},{id:"pass",label:"Passed"}],topics:Array<{id:FindingTopic;label:string}>=[{id:"all",label:"All topics"},{id:"seo",label:"SEO"},{id:"social",label:"Social"},{id:"content",label:"Content"},{id:"accessibility",label:"Accessibility"},{id:"technical",label:"Technical"}];const matches=diagnostics.filter(item=>(statusFilter==="all"||displayStatus(item)===statusFilter)&&(topic==="all"||findingTopics[topic].has(item.id))),matchingIds=new Set(matches.map(item=>item.id));const statusCount=(status:FindingStatusFilter)=>status==="all"?diagnostics.length:diagnostics.filter(item=>displayStatus(item)===status).length;return <section className="findings-explorer" aria-labelledby="findings-heading"><header><div><p className="eyebrow">DIAGNOSTIC FINDINGS</p><h2 id="findings-heading">Inspect the results.</h2></div><p>Showing {matches.length} of {diagnostics.length} checks</p></header><div className="finding-filters"><div role="group" aria-label="Filter findings by status">{statuses.map(filter=><button type="button" className={statusFilter===filter.id?"is-active":""} aria-pressed={statusFilter===filter.id} onClick={()=>setStatusFilter(filter.id)} key={filter.id}>{filter.label} <span>{statusCount(filter.id)}</span></button>)}</div><div role="group" aria-label="Filter findings by topic">{topics.map(filter=><button type="button" className={topic===filter.id?"is-active":""} aria-pressed={topic===filter.id} onClick={()=>setTopic(filter.id)} key={filter.id}>{filter.label}</button>)}</div></div><div className="doctor-findings">{diagnostics.map(item=><div className={`finding-entry${matchingIds.has(item.id)?"":" is-filtered-out"}`} key={item.id}><FindingDetails item={item} pageUrl={pageUrl} /></div>)}</div>{!matches.length&&<div className="finding-empty"><strong>No matching findings.</strong><p>Try another status or topic filter.</p><button type="button" onClick={()=>{setStatusFilter("all");setTopic("all");}}>Show all checks</button></div>}</section>;}
function RecheckCallout({loading,onRecheck}:{loading:boolean;onRecheck:()=>void}){return <section className="doctor-recheck" aria-labelledby="run-again-heading"><div><p className="eyebrow">CHANGED YOUR WEBSITE?</p><h2 id="run-again-heading">Run the diagnosis again.</h2><p>This requests fresh website data and bypasses the recent-result cache. No account is needed, and normal safety limits still apply.</p></div><button type="button" disabled={loading} onClick={onRecheck}>{loading?<LoaderCircle className="doctor-spinner" aria-hidden="true" />:<ArrowRight aria-hidden="true" />} Run again <span aria-hidden="true">→</span></button></section>;}
function DiagnosisFeedback(){const [answer,setAnswer]=useState<"yes"|"no"|null>(null),[submitted,setSubmitted]=useState(false);const reasons:Array<{id:FeedbackReason;label:string}>=[{id:"results-clarity",label:"Results were unclear"},{id:"fix-guidance",label:"Fixes need more guidance"},{id:"speed",label:"The check felt slow"},{id:"missing-check",label:"A useful check was missing"}];function finish(useful:boolean,reason?:FeedbackReason){trackProductEvent("diagnosis_feedback",{useful,reason});setSubmitted(true);}return <section className="doctor-feedback" aria-labelledby="doctor-feedback-heading"><div><p className="eyebrow">QUICK FEEDBACK</p><h2 id="doctor-feedback-heading">Was this diagnosis useful?</h2><p>No account required. Feedback never blocks the report.</p></div>{submitted?<p className="doctor-feedback-thanks" role="status">Thank you for the feedback.</p>:<div className="doctor-feedback-controls"><div role="group" aria-label="Was this diagnosis useful?"><button type="button" onClick={()=>finish(true)}>Yes</button><button type="button" aria-expanded={answer==="no"} aria-controls="feedback-detail" onClick={()=>setAnswer("no")}>No</button></div>{answer==="no"&&<div id="feedback-detail"><p>What could be better? <span>Optional</span></p><div role="group" aria-label="What could be better?">{reasons.map(reason=><button type="button" key={reason.id} onClick={()=>finish(false,reason.id)}>{reason.label}</button>)}</div><button type="button" onClick={()=>finish(false)}>Skip this question</button></div>}</div>}</section>;}
const relatedTools=[{href:"/lab/meta-generator",title:"Meta Tag Generator",description:"Draft a title and description."},{href:"/lab/contrast-checker",title:"Contrast Checker",description:"Test accessible colour combinations."},{href:"/lab/clamp-generator",title:"CSS Clamp Generator",description:"Create responsive fluid values."},{href:"/lab/open-graph-preview",title:"Open Graph Preview",description:"Shape a social sharing card."}];
function RelatedFreeTools(){return <nav className="doctor-related-tools" aria-labelledby="related-tools-heading"><header><p className="eyebrow">MORE FREE TOOLS</p><h2 id="related-tools-heading">Keep making the page better.</h2></header><div>{relatedTools.map((tool,index)=><Link href={tool.href} key={tool.href}><span>{String(index+1).padStart(2,"0")}</span><div><strong>{tool.title}</strong><small>{tool.description}</small></div><ArrowUpRight aria-hidden="true" /></Link>)}</div></nav>;}
// Legacy v1 entries had only these three fields. Optional snapshot fields let
// them load unchanged while new records are ready for future local comparison.
type RecentCheck=Pick<WebDoctorReportSnapshot,"url"|"score"|"checkedAt">&Partial<Pick<WebDoctorReportSnapshot,"schemaVersion"|"categories"|"findings">>;
const RECENT_CHECKS_KEY="web-doctor:recent-checks:v1";
function RecentChecks({items,loading,onAnalyse,onRemove,onClear}:{items:RecentCheck[];loading:boolean;onAnalyse:(url:string)=>void;onRemove:(url:string)=>void;onClear:()=>void}){if(!items.length)return null;return <section className="recent-checks" aria-labelledby="recent-checks-heading"><header><div><p className="eyebrow">RECENT CHECKS</p><h2 id="recent-checks-heading">Stored in this browser.</h2></div><div className="recent-check-actions"><button type="button" disabled title="Result comparison is planned for a future version">Compare previous result <span>Coming later</span></button><button type="button" onClick={onClear}>Clear history</button></div></header><ol>{items.map(item=>{let domain=item.url;try{domain=new URL(item.url).hostname;}catch{}return <li key={item.url}><button type="button" disabled={loading} aria-label={`Run Web Doctor again for ${domain}, previous score ${item.score} out of 100`} onClick={()=>onAnalyse(item.url)}><span>{domain}</span><strong>{item.score}</strong></button><button type="button" aria-label={`Remove ${domain} from recent checks`} onClick={()=>onRemove(item.url)}>Remove</button></li>;})}</ol><p>Saved only in localStorage on this device. No account is required, and this history is never silently uploaded.</p></section>;}
function CheckTrust(){const steps=["We request the public page.","We inspect its public HTML and SEO signals.","We run documented checks.","We return the result."];return <section className="doctor-trust" aria-labelledby="doctor-trust-heading"><header><p className="eyebrow">HOW YOUR CHECK WORKS</p><h2 id="doctor-trust-heading">A transparent diagnosis.</h2><p>No AI is used to calculate your score. The same detected signals produce the same weighted result. <Link href="/lab/web-doctor/changelog">See what has changed</Link>.</p></header><ol>{steps.map((step,index)=><li key={step}><span>{String(index+1).padStart(2,"0")}</span><p>{step}</p></li>)}</ol><a href="#doctor-education-heading">Explore the documented checks <ArrowRight aria-hidden="true" /></a></section>;}
function failureNextAction(message:string){if(/valid website|website URL|HTTP and HTTPS/i.test(message))return "Check the address and try a public HTTP or HTTPS URL.";if(/resolved|hostname/i.test(message))return "Check the spelling and confirm that the domain has a public DNS record.";if(/timeout|did not respond/i.test(message))return "Try again shortly, or paste the page source into Manual HTML Analysis.";if(/authentication/i.test(message))return "Use Manual HTML Analysis with page source you are authorised to access.";if(/refused automated|limiting automated/i.test(message))return "The site may block diagnostic crawlers. You can still use Manual HTML Analysis.";if(/secure connection/i.test(message))return "Check the site's TLS certificate, or use Manual HTML Analysis while it is being repaired.";if(/redirect/i.test(message))return "Review the site's redirect rules for a loop or missing destination.";if(/HTML webpage/i.test(message))return "Choose an HTML page rather than a PDF, image, feed, download or API endpoint.";if(/too large/i.test(message))return "Reduce the page response size, or paste a smaller HTML document into Manual HTML Analysis.";if(/internal|private|reserved/i.test(message))return "For safety, only publicly reachable internet pages can be checked.";if(/server returned an error/i.test(message))return "Try again later after the website's server has recovered.";return "Check the address and try again, or use Manual HTML Analysis.";}
function openManualAnalysis(){const details=document.getElementById("manual-html-analysis") as HTMLDetailsElement|null;if(details){details.open=true;details.scrollIntoView({behavior:"smooth",block:"start"});window.setTimeout(()=>document.getElementById("manual-html")?.focus(),350);}}
function ScoreBreakdown({report}:{report:WebDoctorReport}){const diagnosis=report.score>=80?"Your website is in good shape.":report.score>=60?"Your website has a solid foundation.":"Your website needs focused attention.";return <section className="score-breakdown" aria-labelledby="score-breakdown-heading"><header className="score-editorial-intro"><p className="eyebrow">THE DIAGNOSIS</p><h2 id="score-breakdown-heading">{diagnosis}</h2><p>Six focused chapters make up the deterministic Web Doctor score. This is a diagnostic summary, not a Google ranking score.</p></header><ol className="score-chapters">{report.scoreCategories.map((category,index)=>{const displayScore=Number.isInteger(category.score)?category.score:category.score.toFixed(1);return <li key={category.id}><span>{String(index+1).padStart(2,"0")}</span><div><p>{category.label}</p><strong>{displayScore} <small>/ {category.maximum}</small></strong><span className="sr-only">{category.label} score: {displayScore} out of {category.maximum}.</span><i aria-hidden="true"><b style={{width:`${category.score/category.maximum*100}%`}} /></i></div></li>;})}</ol><details id="scoring-method"><summary>How scoring works</summary><div className="score-method"><p>The score is deterministic. Each check has a fixed weight: PASS earns all available points, IMPROVE earns half, and IMPORTANT earns none. Context-neutral findings earn their available points without pretending an optional feature is required. Category scores are added and rounded to the nearest whole number.</p>{report.scoreCategories.map(category=><section key={category.id}><h3>{category.label} <span>/{category.maximum}</span></h3><ul>{category.checks.map(check=><li key={check.id}><span>{check.label}</span><span>{check.neutral?"Neutral":check.status==="pass"?"Pass":check.status==="warning"?"Improve":"Important"}</span><strong>{check.earned} / {check.weight}</strong></li>)}</ul></section>)}<p>No hreflang on a single-language page, absent robots.txt, absent optional schema, valid empty alt text, and multiple H1 elements by themselves are not treated as automatic failures. Security basics and content overview are informational. Missing Twitter-specific tags receive only a small deduction when complete Open Graph fallback is unavailable.</p></div></details></section>;}
function SearchPreview({report}:{report:WebDoctorReport}){const title=report.diagnostics.find(item=>item.id==="title")?.value;const description=report.diagnostics.find(item=>item.id==="description")?.value;let displayUrl=report.url;try{const parsed=new URL(report.url);displayUrl=`${parsed.hostname}${parsed.pathname==="/"?"":parsed.pathname}`;}catch{}return <section className="search-preview" aria-labelledby="search-preview-heading"><header><div><p className="eyebrow">SEARCH PREVIEW</p><h2 id="search-preview-heading">Preview</h2></div><small>Search engines may display different text.</small></header><div className="search-preview-result"><span>{displayUrl}</span><h3>{title&&title!=="Not found"?title:displayUrl}</h3><p>{description&&description!=="Missing"?description:"No meta description was detected. A search engine may select relevant text from the page."}</p></div></section>;}

export function SeoTool(){
  const [url,setUrl]=useState(""); const [html,setHtml]=useState(""); const [report,setReport]=useState<WebDoctorReport|null>(null);
  const [error,setError]=useState(""); const [loading,setLoading]=useState(false);
  const [enteredUrl,setEnteredUrl]=useState("");
  const [progress,setProgress]=useState<Array<Extract<WebDoctorStreamEvent,{type:"progress"}>>>([]);
  const [recentChecks,setRecentChecks]=useState<RecentCheck[]>([]);
  const resultsHeadingRef=useRef<HTMLHeadingElement>(null);

  useEffect(()=>{const timer=window.setTimeout(()=>{try{const saved=JSON.parse(localStorage.getItem(RECENT_CHECKS_KEY)??"[]") as unknown;if(Array.isArray(saved)){setRecentChecks(saved.filter((item):item is RecentCheck=>Boolean(item&&typeof item==="object"&&typeof (item as RecentCheck).url==="string"&&typeof (item as RecentCheck).score==="number"&&typeof (item as RecentCheck).checkedAt==="string")).slice(0,8));}}catch{}},0);return()=>window.clearTimeout(timer);},[]);
  useEffect(()=>{if(!report||enteredUrl==="Pasted HTML"||!/^https?:\/\//i.test(report.url))return;const timer=window.setTimeout(()=>setRecentChecks(current=>{const next=[createReportSnapshot(report),...current.filter(item=>item.url!==report.url)].slice(0,8);try{localStorage.setItem(RECENT_CHECKS_KEY,JSON.stringify(next));}catch{}return next;}),0);return()=>window.clearTimeout(timer);},[report,enteredUrl]);
  useEffect(()=>{if(!report)return;requestAnimationFrame(()=>resultsHeadingRef.current?.focus());},[report]);
  function removeRecent(recentUrl:string){setRecentChecks(current=>{const next=current.filter(item=>item.url!==recentUrl);try{localStorage.setItem(RECENT_CHECKS_KEY,JSON.stringify(next));}catch{}return next;});}
  function clearRecent(){setRecentChecks([]);try{localStorage.removeItem(RECENT_CHECKS_KEY);}catch{}}

  function normalizeClientUrl(value:string){const candidate=value.trim();if(!candidate)throw new Error("Enter a website URL to analyse.");const hasExplicitScheme=/^[a-z][a-z0-9+.-]*:/i.test(candidate);let parsed:URL;try{parsed=new URL(hasExplicitScheme?candidate:`https://${candidate}`);}catch{throw new Error("Enter a valid website address, such as example.com.");}if(!["http:","https:"].includes(parsed.protocol))throw new Error("Only HTTP and HTTPS website addresses are supported.");if(parsed.username||parsed.password)throw new Error("Website addresses containing login credentials are not supported.");parsed.hash="";return parsed.toString();}
  async function analyse(payload:{url?:string;html?:string},source:AnalysisSource="url"){setLoading(true);setError("");setReport(null);setProgress([]);trackProductEvent("web_doctor_started",{source});const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),65_000);try{const response=await fetch("/api/web-doctor/analyse",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload),signal:controller.signal});if(!response.body)throw new Error("The diagnostic service returned an empty response.");const reader=response.body.getReader();const decoder=new TextDecoder();let buffer="";let finished=false;const consume=(line:string)=>{if(!line.trim())return;const event=JSON.parse(line) as WebDoctorStreamEvent;if(event.type==="progress")setProgress(current=>[...current,event]);else if(event.type==="result"){finished=true;setReport(event.report);const detectedTitle=event.report.diagnostics.find(item=>item.id==="title")?.value??"",detectedDescription=event.report.diagnostics.find(item=>item.id==="description")?.value??"";if(/^https?:\/\//i.test(event.report.url))saveCrossToolState({url:event.report.url,title:detectedTitle==="Not found"?"":detectedTitle,description:detectedDescription==="Missing"?"":detectedDescription});trackProductEvent("web_doctor_completed",{source,scoreBand:scoreBand(event.report.score),importantIssues:event.report.diagnostics.filter(item=>displayStatus(item)==="important").length});}else throw new Error(event.error);};while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value,{stream:!done});const lines=buffer.split("\n");buffer=lines.pop()??"";for(const line of lines)consume(line);if(done)break;}consume(buffer);if(!finished)throw new Error("The diagnostic ended before a report was ready. Please try again.");}catch(reason){const message=reason instanceof DOMException&&reason.name==="AbortError"?"The check took longer than 65 seconds, so it was stopped. The website may be slow or blocking automated checks.":reason instanceof Error?reason.message:"The website could not be analysed.";trackProductEvent("web_doctor_failed",{source,failureClass:failureClass(message)});setError(message);}finally{window.clearTimeout(timeout);setLoading(false);}}
  function submit(event:FormEvent){event.preventDefault();try{normalizeClientUrl(url);const entered=url.trim();setEnteredUrl(entered);void analyse({url:entered});}catch(reason){trackProductEvent("web_doctor_started",{source:"url"});trackProductEvent("web_doctor_failed",{source:"url",failureClass:"validation"});setError(reason instanceof Error?reason.message:"Enter a valid website address.");setReport(null);setProgress([]);}}
  function retry(){try{normalizeClientUrl(url);const entered=url.trim();setEnteredUrl(entered);void analyse({url:entered});}catch(reason){setError(reason instanceof Error?reason.message:"Enter a valid website address.");}}

  return <div className="web-doctor" aria-busy={loading}>
    <section className="doctor-intake" aria-labelledby="doctor-heading"><div><span className="doctor-mark"><Stethoscope aria-hidden="true" /></span><p className="eyebrow">WEB DOCTOR</p><h1 id="doctor-heading">Check your website.</h1><p>Paste a public website address. We’ll fetch the page, inspect its essential technical and on-page signals, then explain exactly what needs attention.</p></div><form onSubmit={submit}><label htmlFor="website-url">Website URL</label><div className="doctor-url-field"><input id="website-url" inputMode="url" autoComplete="url" placeholder="example.com" value={url} aria-describedby={`website-url-help${error?" website-url-error":""}`} aria-invalid={Boolean(error)} onChange={event=>setUrl(event.target.value)} required /><button type="submit" disabled={loading} aria-label={loading?"Analysing website":"Analyse website"}>{loading?<LoaderCircle className="doctor-spinner" aria-hidden="true" />:<ArrowRight aria-hidden="true" />}</button></div><p id="website-url-help" className="doctor-input-privacy">We analyse publicly available website information.<br />No account required. <a href="/privacy">How Web Doctor protects your privacy</a>.</p><div className="doctor-promises"><span>Free website check.</span><span>No signup.</span><span>No AI.</span></div></form></section>
    <CheckTrust />

    {!report&&<RecentChecks items={recentChecks} loading={loading} onAnalyse={recentUrl=>{setUrl(recentUrl);setEnteredUrl(recentUrl);void analyse({url:recentUrl},"recent");}} onRemove={removeRecent} onClear={clearRecent} />}
    {loading&&<div className="doctor-loading"><p className="sr-only" role="status" aria-live="polite" aria-atomic="true">{progress.at(-1)?.message??"Starting website check"}</p><LoaderCircle className="doctor-spinner" aria-hidden="true" /><div><strong aria-hidden="true">{progress.at(-1)?.message??"Starting website check"}</strong><ol className="doctor-progress" aria-label="Analysis progress">{progress.map((item,index)=><li className={index===progress.length-1?"is-current":"is-complete"} aria-current={index===progress.length-1?"step":undefined} key={`${item.stage}-${index}`}><span aria-hidden="true">{index===progress.length-1?"":"✓"}</span>{item.message}</li>)}</ol><small>This check stops automatically if the website does not respond.</small></div></div>}
    {error&&<div id="website-url-error" className="doctor-error" role="alert"><TriangleAlert aria-hidden="true" /><div><strong>We couldn’t analyse this page.</strong><p>{error}</p><small>{failureNextAction(error)}</small><div className="doctor-error-actions"><button type="button" disabled={loading} onClick={retry}>Try again</button><button type="button" onClick={openManualAnalysis}>Analyse HTML manually</button></div></div></div>}

    {report&&<section className="doctor-report" aria-label="Website diagnostic report"><ResultsSummary report={report} enteredUrl={enteredUrl} headingRef={resultsHeadingRef} /><ReportSharing report={report} /><QuickWins diagnostics={report.diagnostics} /><ScoreBreakdown report={report} /><SearchPreview report={report} /><FindingsExplorer diagnostics={report.diagnostics} pageUrl={report.url} key={report.checkedAt} /><RecheckCallout loading={loading} onRecheck={()=>{trackProductEvent("recheck_clicked",{});const freshRequest={url:report.url,refresh:true};void analyse(freshRequest,"recheck");}} /><RecentChecks items={recentChecks} loading={loading} onAnalyse={recentUrl=>{setUrl(recentUrl);setEnteredUrl(recentUrl);void analyse({url:recentUrl},"recent");}} onRemove={removeRecent} onClear={clearRecent} /><RelatedFreeTools /><DiagnosisFeedback /></section>}

    <details id="manual-html-analysis" className="doctor-advanced"><summary>Advanced options</summary><div><p className="eyebrow">FALLBACK ANALYSIS</p><h2>Analyse HTML manually</h2><p>Open your page source, copy the HTML and paste it here. We will analyse the pasted source server-side without requiring the website to accept our crawler.</p><p>This is a fallback for blocked or unpublished pages. For public websites, the URL check above remains the quickest and most complete option.</p><label htmlFor="manual-html">Page HTML</label><textarea id="manual-html" value={html} onChange={event=>setHtml(event.target.value)} placeholder="Paste the complete page HTML here…" /><button type="button" disabled={loading||!html.trim()} onClick={()=>{setEnteredUrl("Pasted HTML");void analyse({html,url:url||undefined},"manual");}}>Analyse HTML manually <ArrowRight aria-hidden="true" /></button></div></details>
  </div>;
}
